// ── 근거 판정 (4세대) ─────────────────────────────────────────────────────────
// 3세대(거리+낙폭)에 **어휘 절**을 하나 더한 것. 1~3세대 로직과 상수는 그대로 두고
// OR 로 절만 추가했다 — 기존에 통과하던 질문의 판정은 한 건도 바뀌지 않는다.
//
// 왜 어휘인가: best / best2mean / spread 는 전부 같은 거리 공간에서 나와 서로 상관이
// 높다(|r| 0.4~0.6). 임계값을 아무리 굴려도 OUT 분포 안쪽에 박힌 IN 은 못 꺼낸다.
// 직교하는 축이 필요하다 — "질문의 내용어가 회수된 청크에 **문자 그대로** 나오는가".
//   데드락            → study/deadlock.md 본문에 "데드락" 이 그대로 있다
//   코사인/BM25       → 각 노트에 그대로 있다
//   sparse / M2       → dev/docs-rag-m2.md 에 그대로 있다
//   러스트/스위프트    → 볼트 어디에도 없다
// 측정: IN 57 / OUT 22 표본에서 OUT 최대 lexHit = 0.750, 오차단 3건은 모두 1.000.
// [2026-09-15 측정 — IN 57 / OUT 22 / 적대적 스트레스 20]
//   골든 오차단 3 → 0 · 음성 대조군 누수 0 → 0 · 골든 27문항 27/27
//   대가: 적대적 스트레스 통과 6/20 → 8/20. 새로 열린 2건은
//     "트랜잭션 로그 파일 크기 관리" (진짜 누수 — 흔한 단어만으로 다 적중)
//     "정렬 알고리즘 병렬 구현" (sorting.md 가 볼트에 있어 애매)
//   볼트 어휘로만 된 질문에는 약하다. 실제 사용자 질문 3건을 살리는 값으로 받아들였다.
//
// [한계 — 손대기 전에 읽을 것]
//   · OUT 22건 위에서 잰 "누수 0" 이다. 표본이 작다.
//   · LEX 의 실제 여유는 "토큰 1개" 다. 0.75~1.00 이 전부 같은 규칙("미적중 0개")이고
//     0.75 로 내리면 즉시 누수 2건. 숫자 여유 0.15 는 착시다.
//   · OUT "도커 이미지 레이어 캐시" 는 노트가 "Docker" 라 한글 "도커" 가 미적중해서
//     우연히 막혔다. 음차 매핑(도커↔docker)을 추가하면 그 순간 샌다 — 하지 마라.
//   · FAR2 는 측정된 값이 아니다. 이 표본에서 0.60~0.70 아무 값이나 성적이 같다.
//   · 성능이 STOP 리스트에 의존한다. 다만 목록이 모자라면 구제를 못 받을 뿐 누수로는
//     가지 않는다(어휘 절이 안 켜지고 3세대 동작으로 되돌아간다). 코퍼스가 아니라
//     한국어 문법에 대한 의존이라 재색인해도 안 깨진다.
const NEAR  = 0.420;   // 1차 절대컷
const FAR   = 0.58;    // 2차 절대 상한
const FALL  = 0.098;   // 2차 낙폭컷
const FAR2  = 0.62;    // 어휘 절 절대 상한 (데드락 b2m=0.5707 에 여유 0.049)
const LEX   = 0.90;    // 어휘 절 컷 — 사실상 "내용어가 하나도 안 빠졌는가"(1.0)
                       // 평탄 구간 0.75 < LEX <= 1.0. 0.75 에서는 누수 2건이 난다.
const WINDOW = 8;      // 거리 특징(best/best2mean/spread)이 보는 창. 3세대부터 고정.
// 어휘는 더 좁게 본다. 측정상 top-4~8 이 전부 (오차단 0, 누수 0, 구제 3/3) 로 같은데
// top-10 부터 누수가 시작된다. 8은 그 경계 바로 앞이라 6으로 두 칸 물러섰다 — 비용 0이다.
const LEX_WINDOW = 6;

// ── 한국어 휴리스틱 토크나이저 (형태소 분석기 없이) ──────────────────────────
// 꼬리(조사/어미) — 긴 것부터, 1회만 제거. 2회 돌리면 "유사도랑"→"유사" 로 과제거된다.
const TAILS = ["이랑","에서","으로","에게","한테","부터","까지","보다","처럼","마다","대로",
  "밖에","조차","라도","이나","하고","에는","과는","와는","이란","라는","이라",
  "은지","는지","한지","인지","이야","예요","이에","해줘","해야","하는",
  "랑","와","과","은","는","이","가","을","를","의","에","도","만","로","다",
  "요","야","지","고","서","며","면","나","까","죠","네","군","데","해","라","게","걸","건"];
// 질문 골격어 — 꼬리를 뗀 뒤 정확히 일치하면 버린다.
// 주의: 이 목록이 비면 어휘 절이 거의 발동하지 않는다(= 3세대로 되돌아간다).
// 목록이 모자라서 생기는 실패는 항상 "통과시켜야 할 걸 막는" 쪽이다 — 누수로는 안 간다.
const STOP = new Set(("뭐 뭘 뭔 뭐야 뭐가 뭔지 무슨 무엇 어떻 어떻게 어떤 어디 언제 누가 얼마 얼마나 왜 " +
  "알려 알려줘 설명 설명해 정리 가르쳐 말해 얘기 이야기 " +
  "차이 다른 다르 달라 비교 각각 중에 중 골라 골라야 선택 고르 골랐 " +
  "써 쓰 쓸 쓴 쓰나 쓰면 쓰는 써야 썼어 썼 사용 적용 " +
  "필요 이유 방법 관계 정확 자꾸 헷갈 헷갈리 그냥 그리고 좀 진짜 혹시 대해 대한 관련 " +
  "에서 으로 에게 한테 부터 까지 보다 처럼 이랑 하고 " +
  "것 거 게 건 걸 수 때 때문 경우 정도 부분 내용 문제 이거 그거 저거 이런 그런 " +
  "있어 없어 되나 되는 된다 맞아 맞나 인가 일까 할까 하면 한다 이란 라면").split(/\s+/));

const RUN = /[가-힣]+|[A-Za-z0-9]+(?:[-+.][A-Za-z0-9]+)*/g;

function contentTokens(q) {
  const out = [], seen = new Set();
  const runs = String(q || "").match(RUN) || [];
  for (const run of runs) {
    let t = run, latin = /^[A-Za-z0-9]/.test(run);
    if (latin) {
      t = t.toLowerCase();
    } else {
      for (const tl of TAILS) {                       // 꼬리 1회만 제거
        if (t.length > tl.length && t.endsWith(tl)) { t = t.slice(0, -tl.length); break; }
      }
    }
    if (t.length < 2 || STOP.has(t)) continue;
    if (!seen.has(t)) { seen.add(t); out.push({ t, latin }); }
  }
  return out;
}

function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function hit(tok, latin, hay) {
  if (!latin) return hay.indexOf(tok) !== -1;
  // 영문/숫자는 단어 경계로 — "m2" 가 "m20" 에 걸리지 않게
  return new RegExp("(?:^|[^a-z0-9])" + esc(tok) + "(?![a-z0-9])").test(hay);
}

// lexHit = 내용어 중 창 안 청크 **본문 또는 노트 경로**에 그대로 나타나는 비율
function lexHitOf(question, win) {
  const toks = contentTokens(question);
  if (!toks.length) return { lexHit: 0, nTok: 0 };
  const hays = win.map(d => ((body(d).pageContent || body(d).text || "") + " " +
                             (srcOf(d) || "")).toLowerCase());
  let n = 0;
  for (const { t, latin } of toks) if (hays.some(h => hit(t, latin, h))) n++;
  return { lexHit: n / toks.length, nTok: toks.length };
}

// ── 문서 형태 흡수 ───────────────────────────────────────────────────────────
function body(d) {
  if (!d || typeof d !== "object") return {};
  return (d.document && typeof d.document === "object") ? d.document : d;
}
function srcOf(d) {
  const m = body(d).metadata;
  return (m && m.source) ? m.source : null;
}
function r4(v) { return Math.round(v * 1e4) / 1e4; }

// ── 본체 ────────────────────────────────────────────────────────────────────
const j = (typeof $json !== "undefined" && $json) ? $json : $input.first().json;
const raw = Array.isArray(j.docs) ? j.docs : [];
// 게이트 바로 앞이 집계 노드(Build Context / Pack Docs)라 질문 문자열이 흘러오지 않는다
// (2026-09-15 실측: Pack Docs 출력 키가 docs 하나뿐이다). 상류에서 직접 가져온다.
// ② 는 '맥락 재작성'(없으면 '질문 정리'), ④ 는 'Loop Over Questions' 가 갖고 있다.
// 맥락 재작성이 앞에 오는 이유: 검색을 **재작성된 질문**으로 했으므로 어휘 절도 같은 질문으로
// 재야 한다. 원문("그건 왜 비싸?")으로 재면 내용어가 1개뿐이라 lexHit 이 0 또는 1 로
// 튀어 게이트가 우연에 좌우된다. 이 워크플로에 맥락 재작성이 없으면 그대로 '질문 정리' 로 떨어진다.
function getQuestion(src) {
  if (typeof src.question === "string" && src.question) return src.question;
  for (const name of ["맥락 재작성", "질문 정리", "Loop Over Questions"]) {
    try {
      const v = $(name).first().json.question;
      if (typeof v === "string" && v) return v;
    } catch (e) { /* 이 워크플로에는 없는 노드 */ }
  }
  return "";
}
const question = getQuestion(j);

// 출처 줄: 창 안에 등장하는 노트를 거리 오름차순 등장 순서로 앞 3개
const seen = [];
for (const d of raw.slice(0, WINDOW)) {
  const s = srcOf(d);
  if (s && seen.indexOf(s) === -1) seen.push(s);
}
const sourcesLine = seen.slice(0, 3).join(", ") || "없음";

const scored = raw.filter(d => d && typeof d === "object" &&
  typeof d.score === "number" && isFinite(d.score));

let out;
if (!scored.length) {
  out = { grounded: false, best: null, best2mean: null, spread: null,
          nearest: "없음", sourcesLine };
} else {
  const asc = scored.slice().sort((a, b) => a.score - b.score).slice(0, WINDOW);
  const best = asc[0].score;
  const best2mean = asc.length >= 2 ? (asc[0].score + asc[1].score) / 2 : best;
  const spread = asc[asc.length - 1].score - best;
  const { lexHit, nTok } = lexHitOf(question, asc.slice(0, LEX_WINDOW));

  const grounded = best2mean < NEAR
                || (best2mean < FAR  && spread > FALL)
                || (best2mean < FAR2 && lexHit >= LEX);      // ← 새 어휘 절

  out = { grounded, best: r4(best), best2mean: r4(best2mean), spread: r4(spread),
          nearest: srcOf(asc[0]) || "없음", sourcesLine,
          lexHit: r4(lexHit), lexTokens: nTok };             // 관측용(하류는 안 읽음)
}

out.noGroundMessage =
  "🔍 노트에서 관련 내용을 찾지 못했어요.\n\n" +
  "검색은 됐지만 결과가 전부 질문과 거리가 멀어서(가장 가까운 노트 `" +
  (out.nearest || "없음") + "`), 지어내지 않고 멈췄습니다.";

return [{ json: { ...j, ...out } }];

// top-K를 노트 단위로 걸러 원문 순서로 되돌린다. DB를 다시 치지는 않는다.
//
// [왜 필요한가]
// topK 16은 거리와 무관하게 늘 16개를 준다. 청크가 거리순이라 한 노트의 앞뒤가 무관한 노트를
// 사이에 두고 끊긴다. 2026-09-11: HNSW 문항이 ef_construction/ef_search 를 답변에서 빠뜨렸는데
// 정작 그 값이 든 심화 청크는 이미 회수돼 있었다. 회수가 아니라 배치가 문제였다.
//
// [2026-09-14 수정 — 청크 수로 뽑던 것을 거리로 바꿨다]
// 처음엔 "top-K에서 2청크 이상 차지한 노트만 남긴다"는 규칙이었다(1청크짜리는 골든 질문
// 12개 전부에서 노이즈였으므로). 이게 틀렸다. 관련성을 거리가 아니라 슬롯 점유 수로 판정하는
// 셈이라, 거리는 가까운데 청크를 적게 가진 정답 노트가 탈락한다.
//   실행 2110 "리랭킹 알려줘" — 거리 2위인 정답 노트가 버려지고 더 먼 노트가 들어갔다.
// 그래서 노트를 best 거리로 줄 세우고, 1위 대비 BAND 안에 드는 노트만 추가한다.
//
// ── [2026-09-15 수정 — 비교형 질문에만 BAND 를 넓힌다] ──────────────────────
// 단일 BAND 1.08 은 "답이 두 노트에 걸친 질문"을 구조적으로 못 푼다. 비교형은 두 주제가
// 서로 다른 노트에 있고, 질문 임베딩은 둘 중 한쪽으로 쏠린다. 그 결과 2위 노트가 1위의
// 1.09~1.34배로 밀려 BAND 밖으로 떨어진다. 측정(골든 27문항, 549청크/94노트):
//
//   질문                          2위(또는 3위) expect 노트          1위 대비   1.08에서
//   CSRF랑 CORS가 헷갈리는데       study/csrf.md                     1.1412    탈락
//   카프카랑 RabbitMQ 중에         study/kafka.md                    1.1665    탈락
//   bge-m3는 다른 임베딩 모델이랑   study/embeddings.md               1.2233    탈락
//   JWT를 세션 쿠키 대신           study/jwt-token-management.md     1.3354    탈락
//   하이브리드 서치랑 리랭킹        study/retrieval-reranking.md      1.0926    탈락
//                                study/hybrid-search.md            1.1174    탈락
//
//   CSRF 문항은 컨텍스트에 CORS 만 들어가 모델이 "CSRF 설명이 없어 비교 불가"로 거절했고
//   ④ 평가 0/0/0, 종합 4.98 → 4.80. 하이브리드 문항은 더 나빴다 — expect 두 개가 다
//   떨어지고 1위였던 무관 노트 dev/docs-rag-m2.md 하나만 컨텍스트에 들어갔다.
//
// [왜 BAND 단독 상향이 아닌가 — 같은 회수율에서 정밀도가 다르다]
//   설정                          expect 회수  무관 노트/질의  평균 ctx
//   현재 1.08 (전체)                22/28       0.23          3,780자
//   단순상향 1.25 (전체)             27/28       0.55          4,756자
//   비교형만 1.28 (채택)             27/28       0.36          4,512자   ← 노이즈 35% 적다
//   절대거리컷 best<=0.48            27/28       1.00          5,348자
//   2위전용 BAND2 1.34              26/28       0.55          4,634자
// 비교형이 아닌 12문항은 선별 결과가 배포본과 **한 글자도 안 바뀐다**(무관 0.33 동일).
// 대가는 비교형 10문항에서만 발생한다: 무관 노트 0.10 → 0.40/질의.
//
// [왜 1.28 인가 — 평탄 구간의 한가운데]
//   회수 27/28 은 BAND_CMP ∈ [1.2233, 1.3272] 전 구간에서 동일하다. 폭 0.104.
//   (이 경계는 이 파일 자체를 node 로 돌려서 확인했다 — 1.2232 → 26/28, 1.3273 → 무관 0.36→0.41)
//     아래 경계 1.2233 = study/embeddings.md (이 값 밑이면 26/28로 떨어진다)
//     위 경계   1.3272 = study/process-and-thread.md 가 CSRF 문항에 노이즈로 끼어드는 값
//   1.28 의 여유는 아래 0.0567 / 위 0.0472. 예전에 코퍼스 변경으로 깨졌던 임계값의
//   여유가 0.0055 였다 — 그보다 한 자릿수 크다.
// [28/28 을 노리지 않은 이유 — 과적합]
//   28/28 은 BAND_CMP >= 1.3355(JWT 한 문항)에서만 열리고, 위로는 1.3663에서 곧바로
//   노이즈가 늘기 시작한다. 쓸 수 있는 폭이 0.031 뿐이고 **한 문항이 가르는 값**이다.
//   게다가 1.34 로 올리면 CSRF 문항에 study/process-and-thread.md 가 딸려 들어온다 —
//   하필 CSRF/CORS 혼동을 풀어달라는 질문에 프로세스/스레드 노트를 얹는 셈이다.
//   JWT 문항은 선별이 아니라 회수 문제로 본다(2위 노트가 정말 33% 멀다). 여기서 안 고친다.
//
// [예산도 함께 올렸다 — 8500 이면 BAND 를 올려도 소용이 없다]
//   카프카 문항: rabbitmq.md 6,688자 + kafka.md 2,955자 = 9,643자 > 8500 → kafka 탈락
//   하이브리드 문항: 6,108자 + hybrid-search.md 2,549자 = 8,657자 > 8500 → 탈락
//   즉 BAND 를 1.40 까지 올려도 8500 에서는 26/28 이 천장이다. 필요한 최소값은 9,643.
//   캐시된 79질의 전체에서 이 설정이 만드는 최대 컨텍스트가 10,363자(스프링 시큐리티 문항)라,
//   11000 은 사실상 아무 데도 안 물린다 — MAX_CTX 를 20000 으로 놔도 결과가 같다.
//   평탄 구간 [9643, ∞), 아래 여유 1,357자.
//
// [비용]
//   평균 컨텍스트 3,780 → 4,512자 (+19%). 한국어 약 2.14자/토큰(로컬 토크나이저 실측)이므로
//   평균 +약 340토큰, 최악(카프카 문항) 6,596 → 9,491자 = +약 1,350토큰.
//   Gemini Flash Lite 의 실제 prefill 증가는 **측정하지 않았다** — 배포 후 확인할 것.
//
// [음성 대조군]
//   이 노드는 `근거 있나?` 통과분만 받는다. 캐시된 OUT 22건(골든 음성 대조군 5건 포함)은
//   전부 `근거 판정`에서 차단되므로(재현 확인: 차단 22 / 누수 0) BAND 변경의 영향이 0이다.
//   비교형 판정이 OUT 9건에 켜지지만 그 질의들은 여기까지 오지 못한다.
//
// [버린 대안]
//   MAX_NOTES 4: 회수 이득 0, 무관 노트 0.36 → 0.59. 기각.
//   절대거리컷(best <= 0.48): 같은 27/28 에 무관 노트 1.00 — 비율컷보다 3배 시끄럽다.
//   2위전용 BAND2: 3위에 있는 expect(embeddings.md, hybrid-search.md)를 구조적으로 못 집는다.
const BAND     = 1.08;   // 기본 — 비교형이 아닌 질문. 배포본과 동일하게 유지한다.
const BAND_CMP = 1.28;   // 비교형 질문. 평탄 구간 [1.22337, 1.32720] 의 거의 한가운데(중앙 1.2753).
const MAX_NOTES = 3;
const MAX_CTX_CHARS = 11000;  // 2026-09-15: 8500 → 11000. 8500 은 BAND 상향을 무력화한다.

// ── 비교 신호 휴리스틱 ──────────────────────────────────────────────────────
// 형태소 분석기 없이 "두 주제를 나란히 놓는 질문인가"만 본다.
// 의도적으로 **중복**시켜 놨다: 골든 27문항에서 아래 아홉 갈래 중 **어느 하나를 빼도
// 회수 27/28 이 그대로다**. 한 토큰에 성능이 걸려 있지 않다는 뜻이다.
// 오판의 방향도 안전하다 —
//   미탐(비교형인데 못 잡음) → BAND 1.08 로 되돌아간다 = 지금 배포본과 같은 동작
//   오탐(아닌데 잡음)       → BAND 가 넓어져 무관 노트가 한둘 늘 뿐, 정답은 안 잃는다
// 알려진 오탐: `과/와` 는 접속 조사라 "결과 ", "효과 " 같은 명사 꼬리에도 걸린다.
//   캐시 79질의 중 `과/와` 로만 비교형이 되는 건 1건("러스트의 소유권과 빌림 규칙")이고
//   그건 음성 대조군이라 여기 도달하지 않는다. 그래도 새 오탐이 나오면 이 갈래부터 의심할 것.
const CMP = new RegExp(
  "[가-힣A-Za-z0-9]랑(?![가-힣])"   + "|" +   // 카프카랑 / 유사도랑
  "[가-힣A-Za-z0-9]이랑"            + "|" +   // 모델이랑
  "[가-힣A-Za-z0-9](?:와|과)(?=\\s|$)" + "|" + // 카프카와 RabbitMQ / CORS과
  "\\bvs\\b"                       + "|" +
  "차이|다른|다르|달라|비교|중에|헷갈|대신", "i");

// 선별 노드 앞이 집계 노드(Build Context)라 질문 문자열이 흘러오지 않을 수 있다.
// `근거 판정` 노드와 같은 패턴 — ② 는 '맥락 재작성'(없으면 '질문 정리'), ④ 는 'Loop Over Questions'.
function getQuestion(src) {
  if (src && typeof src.question === "string" && src.question) return src.question;
  for (const name of ["맥락 재작성", "질문 정리", "Loop Over Questions"]) {
    try {
      const v = $(name).first().json.question;
      if (typeof v === "string" && v) return v;
    } catch (e) { /* 이 워크플로에는 없는 노드 */ }
  }
  return "";
}

const j = (typeof $json !== "undefined" && $json) ? $json : $input.first().json;
const question = getQuestion(j);
const isCompare = CMP.test(question);
// 질문을 못 구하면(=빈 문자열) isCompare 는 false → BAND 1.08 = 현재 배포본 동작.
const band = isCompare ? BAND_CMP : BAND;

const docs = Array.isArray(j.docs) ? j.docs : [];
const body = (d) => d.document || d;
const srcOf = (d) => (body(d).metadata || {}).source || null;
const lineOf = (d) => (((body(d).metadata || {}).loc || {}).lines || {}).from || 0;

// 옵시디언 위키링크는 본문에 파일명을 끌고 들어온다. 형식 규칙에 "출처 쓰지 말 것"이라고
// 적어두긴 했지만 프롬프트로 부탁할 일이 아니다 — 근거 판정과 같은 이유로 여기서 걷어낸다.
const unlink = (s) => String(s || '').replace(/\[\[([^\]|]*\|)?([^\]]*)\]\]/g, '$2');

const owned = {};
for (const d of docs) {
  const s = srcOf(d);
  if (s) (owned[s] = owned[s] || []).push(d);
}

const rank = Object.keys(owned)
  .map((s) => ({ src: s, best: Math.min(...owned[s].map((d) => (typeof d.score === 'number' ? d.score : Infinity))) }))
  .filter((x) => isFinite(x.best))
  .sort((a, b) => a.best - b.best);

let picked = [];
if (rank.length === 0) {
  picked = docs.slice(0, 3);            // 점수가 없다 — 근거 판정이 이미 막았어야 할 모양
} else {
  const limit = rank[0].best * band;
  let used = 0;
  for (const r of rank.slice(0, MAX_NOTES)) {
    if (picked.length && r.best > limit) break;   // 1위는 무조건, 나머지는 BAND 안일 때만
    const chunks = owned[r.src].slice().sort((a, b) => lineOf(a) - lineOf(b));
    const size = chunks.reduce((n, c) => n + (body(c).pageContent || '').length, 0);
    if (picked.length && used + size > MAX_CTX_CHARS) break;
    picked = picked.concat(chunks);
    used += size;
  }
}

// 받은 모양 그대로 돌려준다 — Answer 의 (d.document || d) 매핑이 계속 통해야 한다.
const out = picked.map((d) => {
  const b = body(d);
  const cleaned = { ...b, pageContent: unlink(b.pageContent) };
  return d.document ? { ...d, document: cleaned } : cleaned;
});

// 출처 줄은 실제로 쓴 노트만 적는다. 근거 판정의 것은 top-8 전체라서 한 글자도 안 쓴 노트까지 걸렸다.
const usedSources = Array.from(new Set(out.map(srcOf).filter(Boolean)));

return [{
  json: {
    ...j,
    docs: out,
    pickedNotes: usedSources,
    pickedChunks: out.length,
    ctxChars: out.reduce((n, d) => n + (body(d).pageContent || '').length, 0),
    sourcesLine: usedSources.slice(0, 3).join(', ') || '없음',
    pickBand: band,        // 관측용 — 하류는 안 읽는다
    pickCompare: isCompare,
  },
}];

// ── 결과 조립 ────────────────────────────────────────────────────────────────
// 두 갈래(근거 있음 → Answer / 근거 없음 → 바로 여기)가 합류한다. 호출부가 읽을 것을
// 한 아이템에 평평하게 담아 돌려준다. 호출부는 서브워크플로 **안의 노드 이름을 몰라야**
// 하므로($('근거 판정') 같은 참조가 호출부에 남으면 경계가 새는 것이다) 여기서 전부 꺼낸다.
//
// 근거 없음을 어떻게 넘기나 — 완성된 문장을 돌려주지 않고 `grounded:false` + `text:''` +
// `noGroundMessage` 를 돌려준다. ② 는 출처 줄을 붙일지 말지를, ④ 는 채점 규칙(음성 대조군)
// 을 그 플래그로 가른다. 서브워크플로가 문장을 완성해 버리면 ② 의 "📄 출처: 없음" 같은
// 군더더기가 붙고 ④ 는 차단과 모델 거절을 구분하지 못한다.
const inp  = $input.first().json;
const gate = $('근거 판정').first().json;
const q    = $('입력 정리').first().json;
const packed = ($('Pack Docs').first().json || {}).docs || [];

let pick = null;
try { pick = $('노트 선별').first().json; } catch (e) { pick = null; }   // 근거 없음 갈래

const grounded = !!gate.grounded;
const text = grounded ? String(inp.text || '') : '';   // 차단됐으면 모델을 부르지 않았다

// 리포트가 구성을 손으로 적지 않게 여기서 읽어 넘긴다(④ `Build Report`).
// 코어가 옮겨왔으므로 ④ 의 `Start Run` 은 더 이상 이 노드들을 볼 수 없다.
let answerModel = '?', fallbackModel = '', topK = '?';
try { answerModel = String($('Gemini Chat Model').params.modelName || '?').split('/').pop(); } catch (e) {}
try { fallbackModel = String($('Ollama Chat Model').params.model || ''); } catch (e) {}
try { topK = $('Obsidian Vector Store').params.topK ?? '?'; } catch (e) {}

return [{
  json: {
    question: q.question,            // 검색·게이트·선별이 실제로 쓴 질문
    rawQuestion: q.rawQuestion,      // 사용자가 친 말 (② 후속질문에서 갈린다)
    contextBlock: q.contextBlock,
    text,                            // (②)(④) 근거 없음이면 ''
    grounded,                        // (②)(④)
    noGroundMessage: gate.noGroundMessage,   // (②)(④)
    best: gate.best, best2mean: gate.best2mean, spread: gate.spread,  // (④)
    nearest: gate.nearest,
    lexHit: gate.lexHit === undefined ? null : gate.lexHit,
    lexTokens: gate.lexTokens === undefined ? null : gate.lexTokens,
    gateSourcesLine: gate.sourcesLine,       // top-8 기준 — 관측용
    sourcesLine: pick ? pick.sourcesLine : gate.sourcesLine,   // (②) 실제로 쓴 노트
    pickedNotes: pick ? pick.pickedNotes : [],
    pickedChunks: pick ? pick.pickedChunks : 0,
    ctxChars: pick ? pick.ctxChars : 0,
    pickBand: pick ? pick.pickBand : null,
    pickCompare: pick ? pick.pickCompare : null,
    pickedDocs: pick ? pick.docs : [],       // 모델이 실제로 읽은 것 — 사후 대조용
    docs: packed,                            // (④) 채점 근거는 선별 **전** top-16 이다
    answerModel, fallbackModel, topK,        // (④) 리포트 표기
  },
}];
